def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

def parse_ints(strings):
    result = []
    for s in strings:
        try:
            result.append(int(s))
        except ValueError:
            pass
    return result

def average(nums):
    assert len(nums) > 0, 'nums must be non-empty'
    return sum(nums) / len(nums)

def nth_or_default(items, index, default):
    try:
        return items[index]
    except IndexError:
        return default
